import random

# any 8 whole numbers: at least two leave the same remainder when divided by 7,
# so their difference is a multiple of 7
random.seed(11)
numbers = random.sample(range(100, 1000), 8)
by_remainder = {}
for n in numbers:
    by_remainder.setdefault(n % 7, []).append(n)

print("numbers:", numbers)
for r, group in sorted(by_remainder.items()):
    if len(group) > 1:
        a, b = group[:2]
        print(f"remainder {r}: {a} and {b}, difference {abs(a - b)} = 7 x {abs(a - b) // 7}")
